package io.baozhu.atlas.service;
import io.baozhu.atlas.api.*; import io.baozhu.atlas.domain.*; import io.baozhu.atlas.execution.*; import io.baozhu.atlas.persistence.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class RunOrchestrator { private final PipelineRepository pipelines; private final RunRepository runs; private final TaskRunRepository taskRuns; private final TaskExecutorRegistry registry;
 public RunOrchestrator(PipelineRepository p,RunRepository r,TaskRunRepository t,TaskExecutorRegistry x){pipelines=p;runs=r;taskRuns=t;registry=x;}
 @Transactional public RunResponse start(Long pipelineId,String key){StoredPipeline stored=pipelines.findById(pipelineId);RunResponse existing=runs.findByKey(key);if(existing!=null)return existing;RunResponse created=runs.create(key,pipelineId);runs.transition(created.id(),RunStatus.PENDING,RunStatus.RUNNING,Map.of("phase","running"));PipelineDefinition p=stored.definition();DagValidationResult plan=DagValidator.validate(p);if(!plan.valid())throw new IllegalArgumentException(String.join("; ",plan.errors()));Map<String,TaskDefinition> byKey=p.tasks().stream().collect(java.util.stream.Collectors.toMap(TaskDefinition::key,x->x));long read=0,written=0;List<String> completed=new ArrayList<>();
  for(String keyInOrder:plan.topologicalOrder()){TaskDefinition task=byKey.get(keyInOrder);taskRuns.start(created.id(),task.key());int attempts=0;boolean ok=false;String error=null;while(!ok&&attempts<=task.maxRetries()){attempts++;try{TaskExecutionResult result=registry.get(task.type()).execute(new TaskExecutionContext(created.id(),p,task));read+=result.recordsRead();written+=result.recordsWritten();taskRuns.success(created.id(),task.key(),attempts,result.recordsRead(),result.recordsWritten());completed.add(task.key());ok=true;}catch(RuntimeException e){error=e.getMessage();if(attempts>task.maxRetries())taskRuns.failed(created.id(),task.key(),attempts,error);}}
   if(!ok){Map<String,Object> summary=new LinkedHashMap<>();summary.put("completedTasks",completed);summary.put("failedTask",task.key());summary.put("attempts",attempts);summary.put("recordsRead",read);summary.put("recordsWritten",written);runs.transition(created.id(),RunStatus.RUNNING,RunStatus.FAILED,summary);return runs.findById(created.id());}}
  Map<String,Object> summary=new LinkedHashMap<>();summary.put("completedTasks",completed);summary.put("recordsRead",read);summary.put("recordsWritten",written);runs.transition(created.id(),RunStatus.RUNNING,RunStatus.SUCCESS,summary);return runs.findById(created.id()); }
}
